export function calculateCartTotal(
  items: CartItem[],
  couponCode?: string,
  taxRate: number = 0.08
): CartCalculation {
  const subtotalRaw = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const subtotal = round2(subtotalRaw);

  let discount = 0;
  if (subtotal > 0) {
    if (couponCode === "SAVE10") {
