      discount = 5;
    }
  }

  discount = Math.min(discount, subtotal);
  discount = round2(discount);

  const taxable = round2(subtotal - discount);
  const tax = round2(taxable * taxRate);
  const total = round2(taxable + tax);

  return {
    subtotal,
    discount,
    tax,
    total,
  };
